<template>
  <main class="container python-page"><p class="cdr-title">Elenco</p><p class="cdr-sub">Quem vestiu a camisa do Robson, por número de jogos</p>
    <section class="cdr-grid g2 players-grid"><router-link v-for="player in players" :key="player.name" class="card player" :to="{ name: 'membro', params: { id: player.name, clubId: clubId } }"><div class="ph"><img :src="photo(player.name)" @error="fallback"><span v-if="player.number" class="num">{{ player.number }}</span></div><div class="player-copy"><div class="player-head"><div><div class="nm">{{ player.displayName || player.proName }}</div><div class="tag">{{ player.name }} · {{ position(player.favoritePosition) }}</div></div><div class="ovr">{{ player.proOverall }}</div></div><div class="pstats"><div><b>{{ player.gamesPlayed || 0 }}</b><span>Jogos</span></div><div><b>{{ player.goals || 0 }}</b><span>Gols</span></div><div><b>{{ player.assists || 0 }}</b><span>Assist.</span></div><div><b>{{ player.manOfTheMatch || 0 }}</b><span>Craque</span></div></div><div class="bar"><div class="wbar" :style="{ width: (player.winRate || 0) + '%' }"/></div><div class="tag">{{ Math.round(player.winRate || 0) }}% de vitórias</div></div></router-link></section>
    <h2 v-if="fakes.length" class="cdr-section">Personagens do clube</h2><p v-if="fakes.length" class="cdr-sub">Os craques fictícios que completavam o time</p><section class="cdr-grid g4"><router-link v-for="player in fakes" :key="player.name" class="card legend" :to="{ name: 'membro', params: { id: player.name, clubId: clubId } }"><img :src="photo(player.name)" @error="fallback"><div class="big gold">{{ player.number }}</div><div>{{ player.proName }}</div></router-link></section>
  </main>
</template>
<script>
import membrosService from '../services/membrosService'
import robsonService from '../services/robsonService'
export default { name: 'MembrosList', data: () => ({ players: [], fakes: [] }), computed: { clubId () { return this.$route.params.clubId }, baseUrl () { return process.env.BASE_URL || '/' } }, async mounted () { const members = (await membrosService.getAll(this.clubId)).data; const robsoners = (await robsonService.getAll()).data; this.players = members.map(player => { const r = robsoners.find(item => item.name === player.name); return { ...player, displayName: r ? r.proName : player.proName, number: r && r.number } }); this.fakes = robsoners.filter(item => item.isfake) }, methods: { photo (name) { return this.baseUrl + 'players/' + name + '.png' }, fallback (event) { event.target.src = this.baseUrl + 'players/_default.png' }, position (position) { return { goalkeeper: 'Goleiro', defender: 'Defensor', midfielder: 'Meio-campo', forward: 'Atacante' }[position] || '' } } }
</script>
